import{_ as l,o as t,c as i,j as a,a as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"몬스터 배치 M004","description":"","frontmatter":{},"headers":[],"relativePath":"world/Monster-Batch-M004.md","filePath":"world/Monster-Batch-M004.md"}'),o={name:"world/Monster-Batch-M004.md"};function n(d,h,s,u,c,b){return t(),i("div",null,[...h[0]||(h[0]=[a("h1",{id:"몬스터-배치-m004",tabindex:"-1"},[r("몬스터 배치 M004 "),a("a",{class:"header-anchor",href:"#몬스터-배치-m004","aria-label":'Permalink to "몬스터 배치 M004"'},"​")],-1),a("p",null,"이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.",-1),a("ul",null,[a("li",null,[r("원본 앵커: "),a("code",null,"docs/game-logic/World-Narrative-Atlas.md")]),a("li",null,[r("원본 해시: "),a("code",null,"61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1")])],-1),a("h2",{id:"g02e15-·-전파까마귀-교량합류-일제원",tabindex:"-1"},[r("G02E15 · 전파까마귀 교량합류 '일제원' "),a("a",{class:"header-anchor",href:"#g02e15-·-전파까마귀-교량합류-일제원","aria-label":`Permalink to "G02E15 · 전파까마귀 교량합류 '일제원'"`},"​")],-1),a("ul",null,[a("li",null,"그룹: G02"),a("li",null,"역할군: 시나리오 보스"),a("li",{"scenarios:[G02-SC1,G02-SC2,G02-SC3],states:[S02,S07],houses:[HC02],theaters:[XT02],synthetics:[H02]":""},"연결:")],-1),e('<h3 id="역할·신체" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>시나리오 보스로, 한강 교량 케이블과 송신 점검구 상공에서 여러 가족의 횃대를 한 원으로 묶는 합류체다. 날개깃은 경적 세 번과 점검 종 두 번을 한꺼번에 흉내 내고, 헬멧·막대·손전등 반사와 우산 각도를 눈으로 가른다. 스파크와 변압기 소리만 곤충·작업자의 단서로 이을 뿐 전파의 내용은 읽지 못하며, 절연체 너머 합선 여부는 알지 못한다.</p><h3 id="기원" tabindex="-1">기원 <a class="header-anchor" href="#기원" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>XT02 서해곡창전구의 해풍과 번식기가 겹친 계절, 상암 철탑과 용산 가선에서 따로 배운 음형이 교량 위에서 섞이며 이 원이 생겼다. G02-SC3의 공동 횃대가 몸의 원형이고, 강제 철거 뒤 어린 개체가 학교 통로에 시험 횃대를 만들던 학습이 반경을 넓혔다.</p><h3 id="서식" tabindex="-1">서식 <a class="header-anchor" href="#서식" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>핵심 자리는 S07 용산철도후국 가선 교차점과 한강 교량 점검구 사이 상공이다. 낮에는 S02 서남제작동맹 공장 지붕의 폐열에 흩어졌다가 해풍이 세진 저녁에만 원주로 모이며, 전선 보수 바구니가 올라오면 일부가 그 궤적을 따른다.</p><h3 id="필요·경제" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>먹이는 야간 곤충과 시장 잔여 단백질, 작은 사체이며 둥지에는 벗겨진 세선과 섬유 조각이 들어간다. HC02 현대자동차이 피복을 자주 갈아 재료가 줄면 난간 표지와 우산 손잡이를 뜯어 영역 공격이 늘고, 피복을 방치하면 배설물이 절연체를 덮어 송신 가용시간이 깎인다.</p><h3 id="생애·정비" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>봄에는 번식쌍이 원의 한 호를 나눠 지키다 비번식기에 여러 가족이 합류한다. 깃이 해풍에 상하면 흉내 음이 갈라져 오경보가 늘고, 철거 다음 해에는 같은 점검 종만 들려도 원이 더 빨리 모인다.</p><h3 id="행동·위계" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>번식쌍이 둥지 방어와 먹이 운반을 나눌 뿐 합류 원에는 지휘자가 없다. 일제원은 음형만 공유하는 임시 중심이며, H02 서린이 울음 순서와 비행 방향을 기록해도 작업 중단은 HC02 인간 관제 담당자가 정한다. 한쪽 번식 개체가 사라지면 인접 쌍이 빈 횃대를 시험해 충돌이 는다.</p><h3 id="단계적-위협" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 정찰 개체가 철탑과 난간에서 경적과 점검 종을 따라 하며 음형을 원에 가져온다. 2단계에서는 먹이 신호와 안전 경보가 뒤섞여 작업자 급강하, 통학로 우회, 송신 정지가 연쇄된다. 3단계에서는 같은 점검구에서 오경보가 세 차례 누적되어 한 신호에 무리가 일제히 이동한다.</p><h3 id="전투·대응" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>그물과 총성, 공중 추격은 무리를 주거 골목으로 밀어 모든 경보 음형을 불신하게 만든다. 시각 차단 천과 우산 행렬, 대체 계단으로 동선을 꺾고 곤충 유인등과 점검 종을 다른 철탑으로 옮기면 학습 신호가 갈라진다. 성공은 사체가 아니라 합선 감소, 보행 부상 0, 송신 가용시간, 오경보율로 본다.</p><h3 id="협상·도덕-선택" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>둥지를 한꺼번에 밀어 교량을 즉시 열면 곤충 포식과 주민 경보가 사라지고 보행 아동과 피난민이 대체 급강하 대상이 된다. HC02가 보수 시간대, 통학·피난 우회로, 둥지 존치 구간, 이설 막대, 해풍 주간 임시 횃대를 한 장부에 묶으면 재학습 혼란을 감수하는 대신 같은 기반 시설을 나눌 수 있다. 송신 점검을 번식기 뒤로 미루면 충돌은 줄어도 한 계절 고장 위험을 사람이 안는다.</p><h3 id="시나리오-연결" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G02-SC3 교량 위의 새 신호가 이 합류 원의 무대이며, G02-SC1의 세 경적과 G02-SC2의 급강하 울음이 여기서 한 음형으로 겹친다.</p><h2 id="g02e16-·-전파까마귀-해풍변종-갯깃자리" tabindex="-1">G02E16 · 전파까마귀 해풍변종 &#39;갯깃자리&#39; <a class="header-anchor" href="#g02e16-·-전파까마귀-해풍변종-갯깃자리" aria-label="Permalink to &quot;G02E16 · 전파까마귀 해풍변종 &#39;갯깃자리&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G02"),a("li",null,"역할군: 지역 변종"),a("li",{"scenarios:[G02-SC1,G02-SC2,G02-SC3],states:[S02,S07],houses:[HC02],theaters:[XT02],synthetics:[H02]":""},"연결:")],-1),e('<h3 id="역할·신체-1" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-1" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>지역 변종으로, 서부 수변 폐철탑과 방파제 난간에 섬유·그물 조각을 엮는 해풍형 개체다. 부리 가장자리는 소금기에 닳아 세선보다 젖은 섬유를 고르고, 눈은 해풍에 실린 곤충 띠와 방파제 등대 반사를 읽는다. 내륙 경적 배열보다 파도와 방파제 종을 먼저 기억하며, 전파 내용이나 먼 교량 절연 상태는 알지 못한다.</p><h3 id="기원-1" tabindex="-1">기원 <a class="header-anchor" href="#기원-1" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>XT02 쪽에서 밀려 오는 해풍과 곤충 밀도에 맞춰 비번식기 일부가 서부 수변으로 일시 이동하면서 갈라졌다. 도시 철탑을 철거당한 어린 개체가 난지 갯가의 폐철탑을 시험 횃대로 삼은 뒤, 방파제 종이 먹이 보상이 되어 내년 귀환 위치를 바꿨다.</p><h3 id="서식-1" tabindex="-1">서식 <a class="header-anchor" href="#서식-1" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>건기·해풍 주간에만 S02 공장 지붕을 떠나 서부 수변 폐철탑·방파제 난간에 머문다. 번식기에는 교량 원주로 돌아가지 않고 갯가 횃대를 지키므로, 내륙 합류 원과 같은 저녁에도 공간이 겹치지 않는다.</p><h3 id="필요·경제-1" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-1" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>먹이는 해풍이 몰아 온 곤충과 수변 시장 잔여이며, 둥지 재료는 그물 파편과 젖은 섬유다. 내륙 피복을 끊어도 이 변종은 줄지 않고, 곤충등을 폐철탑으로 옮기면 그 탑이 새로운 먹이터이자 거점이 된다.</p><h3 id="생애·정비-1" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-1" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>해풍이 잦아지면 갯가 횃대를 비우고 공장 지붕으로 돌아가되, 방파제 종이 한 계절 반복되면 귀환을 미룬다. 소금 깃은 담수로 헹구지 않으면 흉내 음이 갈라지고, 강제 철거 뒤에는 인접 어판장 차양에 새 자리를 시험한다.</p><h3 id="행동·위계-1" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-1" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>갯가 횃대에도 지휘자는 없고 음형만 공유한다. 내륙 번식쌍의 경적 흉내를 따라 하지 않으며, H02가 급강하 울음을 정전 전조로 올려도 현장 표식이 방파제 등대이면 사람이 다시 가른다. HC02 관제는 수변 작업 중단만 결정하고 교량 원을 이 변종으로 합산하지 않는다.</p><h3 id="단계적-위협-1" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-1" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 방파제 종과 등대 점멸을 먹이 신호로 외운다. 2단계에서는 곤충등을 따라 폐철탑에 모여 수변 점검 바구니를 덮는다. 3단계에서는 해풍 주간 깃발 없이 어판장 차양까지 시험 횃대가 번져 통학 우산이 없는 해안 보행을 급강하 대상으로 삼는다.</p><h3 id="전투·대응-1" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-1" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>내륙용 우산 행렬은 해안 바람에 접혀 효과가 없고, 드론 추격은 변종을 어판장 골목으로 민다. 곤충등을 끄고 방파제 종을 점검 종과 다른 박자로 바꾸면 학습이 며칠 흔들리며, 그물 없는 시각 차단 천으로 바구니만 가리는 편이 안전하다. 성공 지표는 수변 합선과 해안 보행 부상, 오경보율이다.</p><h3 id="협상·도덕-선택-1" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-1" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>곤충등을 갯가 폐철탑에 남겨 내륙 통학로를 지키면 수변 노동과 어판장이 새 거점의 비용을 진다. 등대를 도시 철탑으로 되돌리면 학교 난간이 다시 시험 횃대가 된다. 해풍 주간 임시 깃발을 방파제에만 달고 이설 막대로 그물 둥지만 옮기는 선택은 송신 복구를 늦추되 아동 통행과 해안 생업을 같은 저녁에 팔지 않는다.</p><h3 id="시나리오-연결-1" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-1" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G02-SC2의 곤충등 이설이 이 변종의 거점을 만들고, G02-SC3의 해풍 주간이 갯가 횃대를 키우며, G02-SC1의 경적 폐기는 방파제 종을 새 먹이 시계로 남긴다.</p><h2 id="g03e01-·-유기견철군-선도성체-쇠걸음" tabindex="-1">G03E01 · 유기견철군 선도성체 &#39;쇠걸음&#39; <a class="header-anchor" href="#g03e01-·-유기견철군-선도성체-쇠걸음" aria-label="Permalink to &quot;G03E01 · 유기견철군 선도성체 &#39;쇠걸음&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 통제자"),a("li",{"scenarios:[G03-SC1,G03-SC2,G03-SC3],states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03]":""},"연결:")],-1),e('<h3 id="역할·신체-2" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-2" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>통제자로, 가장 오래 살아남은 중형 성체다. 녹슨 목줄 고리가 걸을 때마다 철편 소리를 내고, 코는 사람 체취·소독약·냉동 해동 냄새를 가른다. 명령권은 없고 이동을 먼저 제안할 뿐이며, 목걸이 수동형 태그는 H03 이도가 약 2미터 안에서만 읽고 젖은 털과 금속 고리 때문에 자주 놓친다.</p><h3 id="기원-2" tabindex="-1">기원 <a class="header-anchor" href="#기원-2" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>붕괴 뒤 문을 닫은 사설 보호소와 공사장 경비 자리를 오가던 개체가 S03 마곡연구평의회 외벽 공터에서 다른 유랑 가족과 합류했다. 철편 소리가 동료를 모으는 표지가 되면서 사람들은 이 걸음을 선도로 부르게 되었으나, 우두머리로 선출된 적은 없다.</p><h3 id="서식-2" tabindex="-1">서식 <a class="header-anchor" href="#서식-2" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>낮에는 S03 폐쇄 경비 통로와 고가 하부에 쉬고, 하역 잔여가 늘면 S08 노량진남관상회 야간 하역장 가장자리로 내려간다. XT03 물류 진동이 커진 밤에는 냉동고 진입로까지 제안 동선이 길어진다.</p><h3 id="필요·경제-2" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-2" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>단백질 잔여와 버려진 급식 팩, 여과 뒤 밀폐한 물이 밀도를 정한다. HC03 LG생활건강가 폐기 단백질을 너무 단단히 봉하면 이 걸음은 시장 골목으로 우회를 제안하고, 느슨하면 하역장에 과밀이 쌓여 사람 접촉이 는다.</p><h3 id="생애·정비-2" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-2" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>급식이 안정되면 번식보다 영역 방어를 먼저 제안하고, 강제 포획으로 무리가 흩어지면 인식표가 남은 자리로 다시 모인다. 고리가 끊어지면 철편 소리가 사라져 재결속이 늦어지므로, 부러진 고리를 철사로 감는 것은 장식이 아니라 생존 정비다.</p><h3 id="행동·위계-2" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-2" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>곁의 성체 둘이 제안을 받거나 거부하며, 새끼 있는 가족은 별도 보호 권역을 지킨다. H03가 공격성 군집으로 묶어 올려도 HC03 중재자는 개체별 인식표·냄새·동행으로 다시 나눈다. 선도 개체가 침묵해도 가족은 마지막 잠자리를 반복할 뿐 새 명령을 기다리지 않는다.</p><h3 id="단계적-위협-2" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-2" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 특정 인식표와 급식차에만 반응하며 공터 가장자리를 지킨다. 2단계에서는 익숙한 엔진음과 하역 잔여가 여러 가족을 한 통로로 모아 호송 카트를 따라붙게 한다. 3단계에서는 급식 중단이나 기만 포획 뒤 가족별로 시장과 환승 계단을 동시에 점유한다.</p><h3 id="전투·대응-2" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-2" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>직사 탄환과 일괄 포획은 가족을 생활권 밖으로 밀어낼 뿐이다. 차단 펜스, 급식 우회 지점, 소음 감소, 새끼 구역 깃발이 우선이며, 포획은 부상 개체나 실제 공격을 주도한 개체로 제한한다. 성공은 시민 교상 0, 하역 지연 분의 감소, 가족 재결속 비율이다.</p><h3 id="협상·도덕-선택-2" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-2" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>보호소 코드 대조가 끝날 때까지 하역을 늦추면 오판은 줄지만 식품이 녹는다. 현재 동행과 새끼 돌봄을 먼저 등록하면 무리는 안정되나 뒤늦은 옛 보호자 반환 청구와 충돌한다. 유기 이력을 빌미로 선도 개체만 제거하면 48시간이 아니라 며칠의 분산 점유가 남고 시민 제보망이 닫힌다.</p><h3 id="시나리오-연결-2" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-2" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1 녹슨 이름표의 불완전 판독이 이 걸음의 제안과 겹치고, G03-SC2의 엔진음과 G03-SC3의 냉동고 포위는 제안이 거부된 뒤에 벌어진다.</p><h2 id="g03e02-·-유기견철군-유랑개체-빈고리" tabindex="-1">G03E02 · 유기견철군 유랑개체 &#39;빈고리&#39; <a class="header-anchor" href="#g03e02-·-유기견철군-유랑개체-빈고리" aria-label="Permalink to &quot;G03E02 · 유기견철군 유랑개체 &#39;빈고리&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 일반 생태형"),a("li",{"scenarios:[G03-SC1,G03-SC2],states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03]":""},"연결:")],-1),e('<h3 id="역할·신체-3" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-3" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>일반 생태형으로, 목줄 고리가 비어 철편 소리가 거의 나지 않는 단독 유랑 개체다. 후각으로 옛 급식소 체취를 찾고 청각으로 남의 인식표 충돌음을 빌려 동료를 가늠한다. 태그 자체가 없거나 깨져 H03의 근거리 판독에서 자주 공백으로 남는다.</p><h3 id="기원-3" tabindex="-1">기원 <a class="header-anchor" href="#기원-3" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>군중 대피 때 사람과 헤어진 뒤 어느 가족에도 붙지 못한 개체가 공터와 배수구를 오갔다. 빈 고리는 장식이 아니라 재결속에 실패한 이력이다.</p><h3 id="서식-3" tabindex="-1">서식 <a class="header-anchor" href="#서식-3" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S03 외벽 공터 가장자리와 시장 뒤 배수구를 혼자 돌며, 하역 잔여가 풍부한 밤에만 S08 입구까지 접근한다. 낮 인파가 짙으면 고가 하부 그늘에 붙어 움직이지 않는다.</p><h3 id="필요·경제-3" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-3" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>작은 급식 팩 조각과 밀폐 급수 한 모금이면 하루를 넘기고, 단백질이 봉인되면 아동 통로 잔여로 내려간다. 그늘과 물이 동시에 없는 구간에서는 이동을 멈춘다.</p><h3 id="생애·정비-3" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-3" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>냄새와 철편 소리로 소가족을 찾기 전에는 번식하지 않는다. 강제로 우리에 넣으면 먹이를 거부하고, 풀린 뒤에는 같은 급식차를 피한다.</p><h3 id="행동·위계-3" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-3" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 성체의 제안을 따르지 않고 멀리서 냄새만 확인한다. 인식표 소리가 나면 접근했다가, 엔진음이 낯선 사람 손짓과 겹치면 즉시 빠진다. H03 로그의 공백은 이 개체를 없는 셈 하지 말라는 표시다.</p><h3 id="단계적-위협-3" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-3" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 공터 가장자리에 발자국만 남긴다. 2단계에서는 하역 입구의 카트 바퀴를 따라가며 통행을 머뭇거리게 한다. 3단계에서는 기만 포획을 겪은 뒤 환승 계단에 혼자 앉아 통행을 위협하는 것이 아니라 아동 골목의 잔여를 따른다.</p><h3 id="전투·대응-3" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-3" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>단독 포획망은 이 개체를 시장으로 밀어 넣을 뿐이다. 급식 우회 접시를 공터 쪽에 두고 사람이 멈추면 접근을 스스로 끊는다. 빈 고리를 가짜 철편으로 채워 유인하면 이후 구조 호출에도 나오지 않는다.</p><h3 id="협상·도덕-선택-3" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-3" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>빈 개체를 급식 수레에 묶어 기존 가족에 편입시키면 숫자 장부는 채워지나 가짜 혈연이 생기고 새끼 자리가 줄어든다. 유랑 상태로 두면 시장 침입이 늘지만 옛 보호자가 나타났을 때 반환 충돌은 없다. 태그 없는 몸을 처벌 장부에 올리는 순간 협상 창이 닫힌다.</p><h3 id="시나리오-연결-3" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-3" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1에서 읽히지 않는 네 번째 공백이 이 개체이고, G03-SC2의 엔진음은 유랑을 하역로로 끌어 가족 재결속과 착각하게 만든다.</p><h2 id="g03e03-·-유기견철군-하역섭식-내장코" tabindex="-1">G03E03 · 유기견철군 하역섭식 &#39;내장코&#39; <a class="header-anchor" href="#g03e03-·-유기견철군-하역섭식-내장코" aria-label="Permalink to &quot;G03E03 · 유기견철군 하역섭식 &#39;내장코&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 일반 생태형"),a("li",{"scenarios:[G03-SC2,G03-SC3],states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03]":""},"연결:")],-1),e('<h3 id="역할·신체-4" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-4" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>일반 생태형으로, 생선 내장과 냉동 해동 냄새에 코가 고정된 하역 섭식 개체다. 발바닥은 얼음 녹은 바닥에 적응해 미끄러운 하역장만 선호하고, 목줄 조각은 짧아 철편 소리가 낮다. 사람의 손짓보다 해동 냄새의 농도를 먼저 따른다.</p><h3 id="기원-4" tabindex="-1">기원 <a class="header-anchor" href="#기원-4" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>S08 야간 하역의 잔여 축이 안정되자 공터 가족에서 갈라져 하역장 입구를 잠자리로 삼았다. 경비견 혈통의 야간 대기는 남아 있으나 사람을 지키는 임무는 없다.</p><h3 id="서식-4" tabindex="-1">서식 <a class="header-anchor" href="#서식-4" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>핵심은 S08 수산·냉동 잔여물 축과 하역장 그늘이다. 낮에는 배수구로 물러나고, XT03 물류 진동이 커지면 냉동고 진입로 턱까지 코를 민다.</p><h3 id="필요·경제-4" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-4" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>주 자원은 생선 내장과 해동 드립이며, 밀봉이 강화되면 즉시 시장 골목으로 스며든다. 밀폐 급수가 없으면 해동수를 그대로 마셔 밀도가 한곳에 붙는다.</p><h3 id="생애·정비-4" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-4" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>하역 주기가 규칙적일수록 영역 표시 소변이 입구에 쌓이고 번식은 늘지 않는다. 하역이 다른 냉동고로 옮겨지면 사흘 안에 코가 새 드립을 따라가 잠자리가 이동한다.</p><h3 id="행동·위계-4" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-4" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 성체의 공터 제안을 거절하고 하역 축만 지킨다. 같은 내장 냄새의 두세 마리와만 느슨히 먹고, 새끼 가족 권역에는 들어가지 않는다. H03가 하역장 군집으로 합산해도 중재자는 해동 냄새 동선으로 다시 쪼갠다.</p><h3 id="단계적-위협-4" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-4" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 하역이 끝난 뒤에만 내장을 훑는다. 2단계에서는 카트가 멈추기 전에 입구를 막아 하역 분을 늘린다. 3단계에서는 급식이 끊긴 밤 냉동고 턱을 둘러 상인 통행과 겹친다.</p><h3 id="전투·대응-4" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-4" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>하역장 소독을 독먹이로 바꾸면 사체가 수질을 망치고 남은 코가 골목으로 간다. 잔여를 밀폐 통에 담아 공터 우회 접시로 옮기고 입구 소음만 낮추면 카트 간격이 회복된다. 성공은 하역 지연 분과 교상 0이다.</p><h3 id="협상·도덕-선택-4" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-4" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>폐기 단백질을 더 단단히 봉하면 하역장은 깨끗해지나 아동 통로가 대체 먹이터가 된다. 야간 하역을 다른 냉동고로 옮기면 이 코의 기억은 보존되나 S08 상인의 운송·냉동 비용이 오른다. 내장 접시를 미끼 포획으로 쓰면 이후 정규 급식에도 코가 반응하지 않는다.</p><h3 id="시나리오-연결-4" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-4" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC2의 엔진음이 하역로에 가족을 모을 때 이 개체가 입구를 먼저 점하고, G03-SC3의 냉동고 포위에서 내장 축이 쟁점이 된다.</p><h2 id="g03e04-·-유기견철군-주간은신-배수그늘" tabindex="-1">G03E04 · 유기견철군 주간은신 &#39;배수그늘&#39; <a class="header-anchor" href="#g03e04-·-유기견철군-주간은신-배수그늘" aria-label="Permalink to &quot;G03E04 · 유기견철군 주간은신 &#39;배수그늘&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 일반 생태형"),a("li",{"scenarios:[G03-SC1,G03-SC3],states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03]":""},"연결:")],-1),e('<h3 id="역할·신체-5" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-5" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>일반 생태형으로, 낮 인파를 피해 배수구와 고가 하부에 몸을 붙이는 은신 개체다. 눈보다 그늘의 온도 차와 소독약 잔향을 읽고, 짧은 다리로 관 입구를 오간다. 철편은 관벽에 닿지 않게 테이프로 감겨 있어 주간에는 소리가 거의 없다.</p><h3 id="기원-5" tabindex="-1">기원 <a class="header-anchor" href="#기원-5" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>인적 밀도가 높은 낮 시장이 공터를 빼앗자, 하역 가족이 아닌 개체들이 배수·고가 그늘을 잠자리로 학습했다. 테이프는 사람이 감아 준 흔적이 아니라 관 소음에 놀라지 않으려 스스로 문지른 잔여 섬유다.</p><h3 id="서식-5" tabindex="-1">서식 <a class="header-anchor" href="#서식-5" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S03 공터와 S08 시장 사이 배수구, 고가 하부 그늘이 낮의 영역이다. 밤이 되어서야 하역 축에 합류하며, 그늘이 철거되면 환승 계단 밑으로 밀린다.</p><h3 id="필요·경제-5" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-5" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>그늘과 재오염되지 않은 밀폐 급수가 밀도 상한이다. 먹이보다 휴식 공간이 부족할 때 주간 통행로에 드러눕는다.</p><h3 id="생애·정비-5" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-5" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>테이프가 풀리면 관 진동에 놀라 그늘을 버리고 계단으로 나온다. 강제 수색으로 배수구를 비우면 같은 날 저녁 환승 계단에 은신이 재형성된다.</p><h3 id="행동·위계-5" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-5" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 제안이 공터로 향해도 해가 남아 있으면 움직이지 않는다. 새끼 가족과 그늘을 시간 분할로 쓰되 먹이 순서는 겹치지 않는다. H03 주간 로그가 비어도 그늘 열원은 사람이 손전등으로 확인해야 한다.</p><h3 id="단계적-위협-5" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-5" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 배수구 입구에 발자국만 남는다. 2단계에서는 고가 하부에서 주간 보행과 시선이 겹친다. 3단계에서는 그늘이 철거된 뒤 환승 계단을 낮에도 점유한다.</p><h3 id="전투·대응-5" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-5" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>고압 수세와 독성 연막은 개를 골목으로 밀어 교상을 키운다. 대체 그늘 막과 밀폐 급수통을 공터 쪽에 열고 배수구는 부분 차수만 하면 주간 통행이 회복된다. 성공은 주간 조우 거리와 계단 점유 시간이다.</p><h3 id="협상·도덕-선택-5" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-5" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>고가 하부를 상시 조명으로 비워 치안을 얻으면 은신은 환승 계단으로 이동한다. 그늘을 남겨 동물의 낮 휴식을 인정하면 절도 집단이 집결 시각을 창고 빈틈으로 읽을 수 있어, 위치 기록은 지연 공유해야 한다. 주간 은신을 전멸 대상으로 삼으면 보호 윤리와 제보가 함께 무너진다.</p><h3 id="시나리오-연결-5" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-5" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1의 하역장 가장자리 판독이 주간 공백과 어긋날 때 이 그늘이 원인 후보가 되고, G03-SC3에서 계단 점유는 그늘 철거의 대가다.</p><h2 id="g03e05-·-유기견철군-재결속직-철편울음" tabindex="-1">G03E05 · 유기견철군 재결속직 &#39;철편울음&#39; <a class="header-anchor" href="#g03e05-·-유기견철군-재결속직-철편울음" aria-label="Permalink to &quot;G03E05 · 유기견철군 재결속직 &#39;철편울음&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 직능형"),a("li",{"scenarios:[G03-SC1,G03-SC3],states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03]":""},"연결:")],-1),e('<h3 id="역할·신체-6" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-6" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>직능형으로, 목줄 고리와 인식표 조각을 몸 곳곳에 걸어 철편 소리를 재결속 신호로 쓰는 개체다. 청각이 엔진음보다 금속 충돌 주기를 세밀히 가르고, 후각은 동행 개체의 체취를 소리와 겹쳐 확인한다. 태그가 여러 개라 H03는 한 몸을 두 코드로 중복 판독하기 쉽다.</p><h3 id="기원-6" tabindex="-1">기원 <a class="header-anchor" href="#기원-6" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>강제 포획 뒤 흩어진 가족들이 인식표가 남은 개체를 중심으로 다시 모이던 습관이 이 몸에 집중됐다. 철편을 늘리는 행동은 장식이 아니라 분산 재결속망의 표지 노동이다.</p><h3 id="서식-6" tabindex="-1">서식 <a class="header-anchor" href="#서식-6" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>공터와 하역장 사이를 오가며 소리가 잘 반사되는 콘크리트 벽 아래를 고른다. 흙바닥과 침수 구간에서는 신호가 죽어 잘 머물지 않는다.</p><h3 id="필요·경제-6" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-6" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>먹이보다 떨어진 인식표 조각과 철사가 직능 유지재다. 표식을 몰수하면 가족 재결속이 늦어져 시장과 계단에 동시 출현이 는다.</p><h3 id="생애·정비-6" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-6" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>고리가 녹아 소리가 둔해지면 새 철편을 주워 다시 건다. 중복 판독이 사흘 계속되면 중재자가 외형 대조를 하기 전까지 이 개체는 ‘두 마리’로 장부에 남는다.</p><h3 id="행동·위계-6" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-6" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 성체보다 늦게 움직이되, 흩어진 동료를 소리로 불러 소가족을 붙인다. 명령은 없고 표지만 있다. 새끼 권역에서는 소리를 낮춘다.</p><h3 id="단계적-위협-6" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-6" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 공터에서 짧은 철편으로 동료만 부른다. 2단계에서는 하역 통로 반사음을 키워 여러 가족을 한 줄로 모은다. 3단계에서는 기만 미끼로 소리를 당한 뒤 구조 호출과 같은 리듬을 모두 무시한다.</p><h3 id="전투·대응-6" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-6" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>철편 소리를 녹음해 유인하면 단기 포획은 쉬워도 이후 모든 구조 신호가 죽는다. 벽 아래 흡음 천과 우회 급식 접시로 반사만 줄이면 재결속은 공터로 돌아온다. 성공은 가족 재결속 비율과 오호출 감소다.</p><h3 id="협상·도덕-선택-6" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-6" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>인식표 잔존 데이터를 실종 가족 찾기에만 쓰면 중복 판독의 혼란을 감수하면서도 처벌 장부를 만들지 않는다. 철편을 모두 잘라 정숙을 얻으면 재결속망이 무너져 계단 점유가 는다. 가짜 구조 신호로 모이게 한 대가는 진짜 부상을 외면하는 침묵이다.</p><h3 id="시나리오-연결-6" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-6" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1의 서로 다른 보호소 코드 세 개가 한 몸의 중복 판독일 수 있고, G03-SC3의 분산 재결속망은 이 철편 표지 위에 선다.</p><h2 id="g03e06-·-유기견철군-급식기억-공회전귀" tabindex="-1">G03E06 · 유기견철군 급식기억 &#39;공회전귀&#39; <a class="header-anchor" href="#g03e06-·-유기견철군-급식기억-공회전귀" aria-label="Permalink to &quot;G03E06 · 유기견철군 급식기억 &#39;공회전귀&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 직능형"),a("li",{"scenarios:[G03-SC2,G03-SC3],states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03]":""},"연결:")],-1),e('<h3 id="역할·신체-7" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-7" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>직능형으로, 특정 급식차 엔진 공회전과 바퀴 음을 안전한 인간 신호로 기억하는 개체다. 청각이 공회전 주기와 낯선 엔진을 가르고, 후각은 원래 운전자의 체취가 겹칠 때만 경계를 푼다. 손짓만으로는 접근하지 않는다.</p><h3 id="기원-7" tabindex="-1">기원 <a class="header-anchor" href="#기원-7" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>폐쇄된 경비 통로의 급식차가 끊긴 뒤에도 같은 공회전이 재현되면 흩어진 가족이 하역로로 모이던 학습이 몸에 남았다. G03-SC2의 사회 학습이 이 직능의 원형이다.</p><h3 id="서식-7" tabindex="-1">서식 <a class="header-anchor" href="#서식-7" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S03 경비 통로 입구와 S08 하역로 사이에 엔진음이 들리는 밤에만 나타난다. 엔진 없는 이동식 급식소 앞에서는 한 바퀴 밖에서 멈춘다.</p><h3 id="필요·경제-7" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-7" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>급식 팩보다 익숙한 공회전 자체가 접근 조건이다. 차량이 바뀌면 며칠 동안 먹이를 거부해 하역 잔여 의존이 커진다.</p><h3 id="생애·정비-7" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-7" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>원래 운전자가 사라지면 공격성과 먹이 거부가 함께 오른다. 새 운전자의 체취를 급식 절차와 겹쳐 익히는 데 여러 날이 걸리며, 그 기간 하역량을 줄여야 한다.</p><h3 id="행동·위계-7" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-7" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 성체보다 차량을 우선한다. 공회전이 들리면 가족을 하역로로 끌어 제안 권한을 일시적으로 덮는다. H03가 군집 이동으로 기록해도 중재자는 차량 단위로 나눈다.</p><h3 id="단계적-위협-7" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-7" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 옛 통로 앞에서만 귀를 세운다. 2단계에서는 공회전이 재현되자 여러 가족을 카트에 붙인다. 3단계에서는 기만 포획에 엔진음이 쓰인 뒤 모든 차량 접근을 적대한다.</p><h3 id="전투·대응-7" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-7" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>엔진음을 미끼로 우리에 넣으면 통행은 당장 열려도 신뢰가 소모품이 된다. 공회전 없는 이동식 급식소를 매일 다른 자리에 두면 신호는 보존되나 인력과 냉장이 든다. 성공은 하역 회복 속도와 재학습 일수, 교상 0이다.</p><h3 id="협상·도덕-선택-7" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-7" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>원래 운전자 한 사람에게 의존하면 즉시 통로가 비지만 그 사람의 부재가 합의 전체를 무너뜨린다. 새 운전자를 천천히 익히면 며칠의 배급 손실을 사람이 진다. 신뢰를 속여 빠르게 안전을 사는 선택은 이후 구조 인력까지 적으로 만든다.</p><h3 id="시나리오-연결-7" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-7" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC2 급식차를 기억하는 무리가 이 직능의 무대이고, G03-SC3에서 급식 중단이 겹치면 공회전 없는 밤의 포위가 된다.</p><h2 id="g03e07-·-유기견철군-보육직능-새끼막" tabindex="-1">G03E07 · 유기견철군 보육직능 &#39;새끼막&#39; <a class="header-anchor" href="#g03e07-·-유기견철군-보육직능-새끼막" aria-label="Permalink to &quot;G03E07 · 유기견철군 보육직능 &#39;새끼막&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 직능형"),a("li",{"scenarios:[G03-SC1,G03-SC3],states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03]":""},"연결:")],-1),e('<h3 id="역할·신체-8" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-8" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>직능형으로, 새끼가 있는 가족의 별도 보호 권역을 지키는 성체다. 몸집이 선도 개체보다 작아도 그늘 막 안에서 접근하는 코를 먼저 막고, 소독약 냄새와 낯선 손짓을 위협으로 기억한다. 태그 판독은 새끼 쪽이 더 자주 누락된다.</p><h3 id="기원-8" tabindex="-1">기원 <a class="header-anchor" href="#기원-8" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>하역 잔여가 늘며 여러 가족이 연합할 때, 새끼를 둔 쌍이 공터 한 귀퉁이를 잠자리로 고정하면서 보육 권역이 생겼다. 선도 제안도 이 막 앞에서는 거부된다.</p><h3 id="서식-8" tabindex="-1">서식 <a class="header-anchor" href="#서식-8" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S03 공터 그늘과 하역장에서 한 골목 떨어진 건조 바닥이다. 냉동고 진입로에는 새끼를 데려가지 않으며, 진동이 커지면 배수구 쪽으로 옮긴다.</p><h3 id="필요·경제-8" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-8" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>성체 몫보다 새끼용 급식 팩과 그늘, 밀폐 물이 우선이다. 배급이 하역장에만 모이면 보육 막이 비어 새끼가 카트 바퀴에 노출된다.</p><h3 id="생애·정비-8" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-8" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>급식이 안정되어도 번식이 폭발하지 않고 막 방어만 강해진다. 포획으로 성체가 빠지면 남은 인식표 소리로 막이 다시 서지만 새끼 생존은 그 전에 떨어진다.</p><h3 id="행동·위계-8" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-8" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>명령 체계 밖의 거부권이다. 선도 성체와 철편 직능이 하역로로 가도 막은 남는다. HC03 깃발이 새끼 구역을 표시하면 그 안에서만 접근을 참는다.</p><h3 id="단계적-위협-8" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-8" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 공터 귀퉁이에 막만 있다. 2단계에서는 급식 수레가 막을 가로질러 새끼가 수레를 따라가다 놓친다. 3단계에서는 급식 중단 후 막이 환승 계단 밑으로 옮겨 진다.</p><h3 id="전투·대응-8" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-8" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>막 전체를 포획하면 신뢰가 무너져 성체가 시장으로 분산된다. 부상 성체만 비살상으로 빼고 막을 그늘에 남겨 두면 통행 회복은 느려도 새끼 권역은 유지된다. 성공은 새끼 동반 재결속과 교상 0이다.</p><h3 id="협상·도덕-선택-8" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-8" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>급식 수레로 가족을 분리해 태그를 확인하면 하역은 빨라지나 수레를 못 따른 새끼가 떨어진다. 현재 동행 관계를 코드보다 우선 등록하면 옛 소유 청구와 충돌한다. 사람의 통행을 위해 보육 막을 지우는 일은 동물의 현재 가족을 삭제하는 선택이다.</p><h3 id="시나리오-연결-8" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-8" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1의 분리 선택지가 이 막을 시험하고, G03-SC3의 가족별 급식 구역은 막을 공식 비용으로 인정하는 길이다.</p><h2 id="g03e08-·-유기견철군-첫정예-카트이빨" tabindex="-1">G03E08 · 유기견철군 첫정예 &#39;카트이빨&#39; <a class="header-anchor" href="#g03e08-·-유기견철군-첫정예-카트이빨" aria-label="Permalink to &quot;G03E08 · 유기견철군 첫정예 &#39;카트이빨&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 첫 번째 정예"),a("li",{"scenarios:[G03-SC2,G03-SC3],states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03]":""},"연결:")],-1),e('<h3 id="역할·신체-9" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-9" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>첫 번째 정예로, 호송 카트 바퀴와 사람 발목 높이를 이빨 높이로 학습한 중형 성체다. 후각은 카트에 묻은 해동 드립과 소독약을 가르고, 청각은 카트 축의 삐걱임을 엔진음과 분리한다. 실제 교상을 주도할 수 있는 개체이며, 태그 판독은 금속 목줄 때문에 한쪽만 읽히는 일이 많다.</p><h3 id="기원-9" tabindex="-1">기원 <a class="header-anchor" href="#기원-9" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>2단계 가족 재결속에서 여러 가족이 한 통로로 모일 때, 카트를 따라붙다 저항한 개체가 이빨 거리를 기억했다. 경비견 이력의 추격 학습이 남아 있으나 주인은 없고, 기만 포획을 한 번 당한 뒤 카트 자체를 위협으로 저장했다.</p><h3 id="서식-9" tabindex="-1">서식 <a class="header-anchor" href="#서식-9" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S08 하역 통로와 환승 계단이 만나는 짧은 직선이다. 공터에서는 선도 성체 뒤에 머물고, XT03 진동과 급식 중단이 겹친 밤에만 냉동고 턱으로 나온다.</p><h3 id="필요·경제-9" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-9" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>카트에 묻은 잔여 단백질이 주 자원이라 밀봉이 강화되면 바퀴 대신 사람 가방을 따른다. 급수와 그늘이 부족하면 이빨 사용 전 경고 시간이 짧아진다.</p><h3 id="생애·정비-9" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-9" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>이빨이 상하면 카트 고무를 씹어 높이를 재조정한다. 비살상 포획 후 치료되어 원래 동행군에 합류한 비율이 낮으면, 이 정예는 단독 추격으로 남는다.</p><h3 id="행동·위계-9" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-9" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 제안보다 카트 이동을 우선하는 예외다. 새끼 막 앞에서는 이빨을 쓰지 않으나 기만 신호가 겹치면 막을 지키려다 통행자를 문다. 중재자는 공격 주도 개체로만 따로 적는다.</p><h3 id="단계적-위협-9" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-9" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>1단계에서는 카트 옆을 걸으며 바퀴만 냄새 맡는다. 2단계에서는 호송 줄을 막아 하역 분을 끌어올린다. 3단계에서는 급식 중단·기만 포획 이후 시장과 계단에서 발목 높이를 먼저 공격한다.</p><h3 id="전투·대응-9" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-9" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>직사로 이 개체만 제거하면 남은 가족이 더 넓은 생활권으로 흩어진다. 차단 펜스로 카트 궤적을 새끼 막과 분리하고, 교상을 주도한 이 개체만 비살상 포획하는 상한이 원칙이다. 철편 소리를 미끼로 쓰면 정예뿐 아니라 구조 호출 전체가 죽는다.</p><h3 id="협상·도덕-선택-9" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-9" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>야간 하역을 다른 냉동고로 옮겨 이빨 거리를 비우면 동물 기억은 지키지만 상인 비용이 오른다. 포획 개체를 교환 자원으로 삼으면 협상 창이 닫힌다. 통행권을 위해 카트 기억을 지울 것인지는 인간이 추가 비용으로 답을 내야 한다.</p><h3 id="시나리오-연결-9" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-9" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC2에서 카트를 따라붙는 재결속의 앞줄이 이 정예이고, G03-SC3의 부상 개체 제한 포획 선택지가 이빨의 상한을 정한다.</p>',20)])])}const P=l(o,[["render",n]]);export{p as __pageData,P as default};
